<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Ubuntu Desktop</title>
  <style>
    :root {
      --bg: #17131d;
      --panel: #211c29;
      --panel-2: #2b2534;
      --panel-3: #352d40;
      --text: #f4eef7;
      --muted: #aaa0b2;
      --accent: #e95420;
      --accent-light: #ff8a5c;
      --border: rgba(255,255,255,.1);
      --shadow: 0 18px 45px rgba(0,0,0,.48);
    }

    * { box-sizing: border-box; }

    html, body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      font-family: Arial, Helvetica, sans-serif;
      color: var(--text);
      background: var(--bg);
    }

    button, textarea { font: inherit; }

    #desktop {
      position: relative;
      width: 100vw;
      height: 100vh;
      min-width: 420px;
      min-height: 300px;
      overflow: hidden;
      background:
        radial-gradient(circle at 72% 22%, rgba(126, 55, 104, .42), transparent 31%),
        radial-gradient(circle at 20% 82%, rgba(53, 37, 91, .55), transparent 36%),
        linear-gradient(135deg, #15101d 0%, #251532 52%, #11151f 100%);
    }

    #desktop::before {
      content: "";
      position: absolute;
      inset: 0;
      opacity: .22;
      pointer-events: none;
      background:
        linear-gradient(115deg, transparent 0 43%, rgba(255,255,255,.08) 43.1% 43.3%, transparent 43.4%),
        linear-gradient(25deg, transparent 0 55%, rgba(255,255,255,.05) 55.1% 55.3%, transparent 55.4%);
    }

    .topbar {
      height: 34px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 16px;
      position: relative;
      z-index: 10;
      background: rgba(13, 11, 17, .8);
      border-bottom: 1px solid rgba(255,255,255,.06);
      font-size: 13px;
    }

    .top-left, .top-right {
      display: flex;
      align-items: center;
      gap: 17px;
    }

    .brand {
      font-weight: bold;
      letter-spacing: .2px;
    }

    .top-icon { color: #d6c8dc; }

    .workspace {
      position: absolute;
      top: 34px;
      right: 0;
      bottom: 66px;
      left: 0;
    }

    .welcome {
      position: absolute;
      left: 34px;
      top: 30px;
      color: rgba(255,255,255,.52);
      user-select: none;
    }

    .welcome strong {
      display: block;
      font-size: 22px;
      color: rgba(255,255,255,.78);
      margin-bottom: 6px;
    }

    #taskbar {
      position: absolute;
      z-index: 100;
      left: 50%;
      bottom: 12px;
      transform: translateX(-50%);
      height: 54px;
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 7px 10px;
      border: 1px solid rgba(255,255,255,.14);
      border-radius: 16px;
      background: rgba(28, 23, 35, .9);
      box-shadow: 0 8px 25px rgba(0,0,0,.38);
      backdrop-filter: blur(12px);
    }

    .launcher {
      width: 42px;
      height: 40px;
      border: 0;
      border-radius: 11px;
      color: var(--text);
      background: transparent;
      cursor: pointer;
      transition: .18s ease;
      font-size: 22px;
    }

    .launcher:hover {
      background: var(--accent);
      transform: translateY(-3px);
    }

    .launcher:active { transform: translateY(0); }

    .window {
      position: absolute;
      z-index: 20;
      display: none;
      flex-direction: column;
      width: 580px;
      height: 420px;
      min-width: 360px;
      min-height: 240px;
      overflow: hidden;
      border: 1px solid rgba(255,255,255,.16);
      border-radius: 10px;
      background: var(--panel);
      box-shadow: var(--shadow);
    }

    #files-window { left: 8%; top: 9%; }
    #notepad-window { left: 27%; top: 14%; }

    .window-head {
      height: 42px;
      flex: 0 0 42px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 12px 0 16px;
      cursor: move;
      user-select: none;
      background: linear-gradient(#3a3043, #302839);
      border-bottom: 1px solid var(--border);
    }

    .window-title {
      display: flex;
      align-items: center;
      gap: 9px;
      font-size: 14px;
      font-weight: bold;
    }

    .window-title .app-symbol {
      color: var(--accent-light);
      font-size: 16px;
    }

    .win-close {
      width: 25px;
      height: 25px;
      border: 0;
      border-radius: 50%;
      color: #fff;
      background: transparent;
      cursor: pointer;
      font-size: 18px;
      line-height: 20px;
    }

    .win-close:hover { background: #c94332; }

    .window-body {
      min-height: 0;
      flex: 1;
      display: flex;
      flex-direction: column;
    }

    .files-toolbar {
      display: flex;
      align-items: center;
      gap: 9px;
      padding: 10px 12px;
      background: #27212e;
      border-bottom: 1px solid var(--border);
    }

    .toolbar-button {
      width: 32px;
      height: 29px;
      border: 1px solid var(--border);
      border-radius: 6px;
      color: var(--text);
      background: var(--panel-3);
      cursor: pointer;
    }

    .toolbar-button:hover { background: var(--accent); }

    #files-path {
      flex: 1;
      padding: 6px 10px;
      overflow: hidden;
      white-space: nowrap;
      text-overflow: ellipsis;
      border-radius: 5px;
      color: #e8dfe9;
      background: #19151f;
      font-family: monospace;
      font-size: 13px;
    }

    #files-list {
      flex: 1;
      min-height: 0;
      overflow: auto;
      padding: 12px;
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(125px, 1fr));
      align-content: start;
      gap: 7px;
    }

    .fs-item {
      min-height: 82px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 7px;
      padding: 8px;
      border: 1px solid transparent;
      border-radius: 8px;
      color: var(--text);
      cursor: default;
      user-select: none;
      text-align: center;
      font-size: 13px;
    }

    .fs-item:hover {
      background: rgba(233,84,32,.18);
      border-color: rgba(233,84,32,.4);
    }

    .fs-icon { font-size: 29px; color: #e9a83b; }
    .fs-item.file .fs-icon { color: #b8b1c5; }

    .statusbar {
      padding: 7px 13px;
      color: var(--muted);
      border-top: 1px solid var(--border);
      font-size: 12px;
    }

    #tabs {
      height: 39px;
      flex: 0 0 39px;
      display: flex;
      align-items: stretch;
      gap: 3px;
      padding: 4px 8px 0;
      overflow-x: auto;
      background: #211b28;
      border-bottom: 1px solid var(--border);
    }

    .tab {
      min-width: 105px;
      max-width: 175px;
      display: flex;
      align-items: center;
      gap: 7px;
      padding: 0 7px 0 12px;
      border: 1px solid transparent;
      border-bottom: 0;
      border-radius: 7px 7px 0 0;
      color: var(--muted);
      background: transparent;
      cursor: pointer;
      font-size: 12px;
    }

    .tab.active {
      color: var(--text);
      background: #30283a;
      border-color: var(--border);
    }

    .tab-name {
      flex: 1;
      overflow: hidden;
      white-space: nowrap;
      text-overflow: ellipsis;
    }

    .tab-close {
      border: 0;
      padding: 1px 4px;
      border-radius: 4px;
      color: var(--muted);
      background: transparent;
      cursor: pointer;
    }

    .tab-close:hover { color: white; background: #a43c35; }

    #new-tab {
      align-self: center;
      width: 28px;
      height: 27px;
      border: 0;
      border-radius: 6px;
      color: var(--text);
      background: transparent;
      cursor: pointer;
      font-size: 20px;
    }

    #new-tab:hover { background: var(--accent); }

    #editor {
      flex: 1;
      width: 100%;
      min-height: 0;
      resize: none;
      border: 0;
      outline: none;
      padding: 18px;
      color: #f7f0f7;
      background: #18141d;
      caret-color: var(--accent-light);
      font-family: "Courier New", monospace;
      font-size: 14px;
      line-height: 1.6;
    }

    .notepad-status {
      height: 26px;
      flex: 0 0 26px;
      padding: 5px 12px;
      color: var(--muted);
      background: #211b28;
      border-top: 1px solid var(--border);
      font-size: 11px;
    }

    @media (max-width: 700px) {
      .window { left: 12px !important; top: 48px !important; width: calc(100vw - 24px); }
      .welcome { display: none; }
    }
  </style>
</head>
<body>
  <main id="desktop">
    <header class="topbar">
      <div class="top-left">
        <span class="brand">Activities</span>
        <span>Ubuntu Desktop</span>
      </div>
      <div class="top-right">
        <span class="top-icon">⌁</span>
        <span class="top-icon">⌁</span>
        <span id="clock">12:00</span>
      </div>
    </header>

    <section class="workspace">
      <div class="welcome">
        <strong>Welcome back</strong>
        <span>A quiet place to get things done.</span>
      </div>

      <section id="files-window" class="window" aria-label="Files window">
        <div class="window-head">
          <div class="window-title"><span class="app-symbol">▣</span> Files</div>
          <button class="win-close" aria-label="Close Files">×</button>
        </div>
        <div class="window-body">
          <div class="files-toolbar">
            <button id="files-up" class="toolbar-button" title="Parent folder" aria-label="Go to parent folder">↑</button>
            <div id="files-path">/</div>
          </div>
          <div id="files-list" aria-label="File listing"></div>
          <div id="files-status" class="statusbar"></div>
        </div>
      </section>

      <section id="notepad-window" class="window" aria-label="Notepad window">
        <div class="window-head">
          <div class="window-title"><span class="app-symbol">✎</span> Notepad</div>
          <button class="win-close" aria-label="Close Notepad">×</button>
        </div>
        <div class="window-body">
          <div id="tabs"></div>
          <textarea id="editor" spellcheck="false" aria-label="Text editor"></textarea>
          <div class="notepad-status">Plain text · Saved automatically</div>
        </div>
      </section>
    </section>

    <nav id="taskbar" aria-label="Application dock">
      <button id="open-files" class="launcher" title="Open Files" aria-label="Open Files">▣</button>
      <button id="open-notepad" class="launcher" title="Open Notepad" aria-label="Open Notepad">✎</button>
    </nav>
  </main>

  <script>
    (() => {
      const $ = (selector) => document.querySelector(selector);

      const filesWindow = $("#files-window");
      const notepadWindow = $("#notepad-window");

      $("#open-files").addEventListener("click", () => {
        filesWindow.style.display = "flex";
        filesWindow.style.zIndex = ++window.topZ;
      });

      $("#open-notepad").addEventListener("click", () => {
        notepadWindow.style.display = "flex";
        notepadWindow.style.zIndex = ++window.topZ;
      });

      document.querySelectorAll(".win-close").forEach((button) => {
        button.addEventListener("click", (event) => {
          event.currentTarget.closest(".window").style.display = "none";
        });
      });

      window.topZ = 20;

      const filesystem = {
        "/": [
          { name: "bin", type: "folder" },
          { name: "etc", type: "folder" },
          { name: "home", type: "folder" },
          { name: "usr", type: "folder" },
          { name: "var", type: "folder" }
        ],
        "/bin": [
          { name: "bash", type: "file" },
          { name: "ls", type: "file" },
          { name: "mkdir", type: "file" }
        ],
        "/etc": [
          { name: "hosts", type: "file" },
          { name: "hostname", type: "file" },
          { name: "profile", type: "file" }
        ],
        "/home": [
          { name: "user", type: "folder" }
        ],
        "/home/user": [
          { name: "Documents", type: "folder" },
          { name: "Downloads", type: "folder" },
          { name: "Pictures", type: "folder" },
          { name: "readme.txt", type: "file" }
        ],
        "/home/user/Documents": [
          { name: "notes.txt", type: "file" },
          { name: "projects", type: "folder" }
        ],
        "/home/user/Documents/projects": [
          { name: "ideas.md", type: "file" }
        ],
        "/home/user/Downloads": [
          { name: "welcome.pdf", type: "file" }
        ],
        "/home/user/Pictures": [
          { name: "wallpaper.png", type: "file" }
        ],
        "/usr": [
          { name: "bin", type: "folder" },
          { name: "lib", type: "folder" },
          { name: "share", type: "folder" }
        ],
        "/var": [
          { name: "log", type: "folder" },
          { name: "tmp", type: "folder" }
        ],
        "/usr/bin": [
          { name: "python3", type: "file" },
          { name: "nano", type: "file" }
        ],
        "/usr/lib": [],
        "/usr/share": [],
        "/var/log": [
          { name: "system.log", type: "file" }
        ],
        "/var/tmp": []
      };

      let currentPath = "/";
      const filesList = $("#files-list");
      const filesPath = $("#files-path");
      const filesStatus = $("#files-status");

      function renderFiles() {
        filesPath.textContent = currentPath;
        filesList.innerHTML = "";
        const entries = filesystem[currentPath] || [];

        entries.forEach((entry) => {
          const item = document.createElement("div");
          item.className = "fs-item " + entry.type;
          item.dataset.type = entry.type;
          item.dataset.name = entry.name;
          item.title = entry.type === "folder" ? "Double-click to open folder" : entry.name;

          const icon = document.createElement("span");
          icon.className = "fs-icon";
          icon.textContent = entry.type === "folder" ? "▰" : "▤";

          const label = document.createElement("span");
          label.textContent = entry.name;

          item.append(icon, label);
          item.addEventListener("dblclick", () => {
            if (entry.type === "folder") {
              currentPath = currentPath === "/" ? "/" + entry.name : currentPath + "/" + entry.name;
              renderFiles();
            }
          });
          filesList.appendChild(item);
        });

        filesStatus.textContent = entries.length + (entries.length === 1 ? " item" : " items");
      }

      $("#files-up").addEventListener("click", () => {
        if (currentPath !== "/") {
          const parts = currentPath.split("/").filter(Boolean);
          parts.pop();
          currentPath = parts.length ? "/" + parts.join("/") : "/";
          renderFiles();
        }
      });

      renderFiles();

      const storageKey = "ubuntu-notepad-tabs-v1";
      let noteState = { active: 0, tabs: [{ name: "Untitled 1", content: "" }] };

      try {
        const saved = JSON.parse(localStorage.getItem(storageKey));
        if (saved && Array.isArray(saved.tabs) && saved.tabs.length) {
          noteState.tabs = saved.tabs.map((tab, index) => ({
            name: typeof tab.name === "string" ? tab.name : "Untitled " + (index + 1),
            content: typeof tab.content === "string" ? tab.content : ""
          }));
          noteState.active = Math.max(0, Math.min(Number(saved.active) || 0, noteState.tabs.length - 1));
        }
      } catch (error) {}

      const tabs = $("#tabs");
      const editor = $("#editor");

      function saveNotes() {
        try {
          localStorage.setItem(storageKey, JSON.stringify(noteState));
        } catch (error) {}
      }

      function renderNotes() {
        tabs.innerHTML = "";
        noteState.tabs.forEach((tab, index) => {
          const tabElement = document.createElement("div");
          tabElement.className = "tab" + (index === noteState.active ? " active" : "");
          tabElement.dataset.index = index;

          const name = document.createElement("span");
          name.className = "tab-name";
          name.textContent = tab.name;

          const close = document.createElement("button");
          close.className = "tab-close";
          close.type = "button";
          close.title = "Close tab";
          close.textContent = "×";
          close.addEventListener("click", (event) => {
            event.stopPropagation();
            if (noteState.tabs.length === 1) {
              noteState.tabs[0] = { name: "Untitled 1", content: "" };
              noteState.active = 0;
            } else {
              noteState.tabs.splice(index, 1);
              if (noteState.active >= noteState.tabs.length) noteState.active = noteState.tabs.length - 1;
              else if (index < noteState.active) noteState.active--;
            }
            saveNotes();
            renderNotes();
          });

          tabElement.append(name, close);
          tabElement.addEventListener("click", () => {
            noteState.tabs[noteState.active].content = editor.value;
            noteState.active = index;
            renderNotes();
          });
          tabs.appendChild(tabElement);
        });

        const add = document.createElement("button");
        add.id = "new-tab";
        add.type = "button";
        add.title = "New tab";
        add.textContent = "+";
        add.addEventListener("click", () => {
          noteState.tabs[noteState.active].content = editor.value;
          noteState.tabs.push({
            name: "Untitled " + (noteState.tabs.length + 1),
            content: ""
          });
          noteState.active = noteState.tabs.length - 1;
          saveNotes();
          renderNotes();
        });
        tabs.appendChild(add);

        editor.value = noteState.tabs[noteState.active].content;
      }

      editor.addEventListener("input", () => {
        noteState.tabs[noteState.active].content = editor.value;
        saveNotes();
      });

      renderNotes();
      saveNotes();

      function makeDraggable(win) {
        const head = win.querySelector(".window-head");
        let dragging = false, offsetX = 0, offsetY = 0;

        head.addEventListener("pointerdown", (event) => {
          if (event.target.closest(".win-close")) return;
          dragging = true;
          win.style.zIndex = ++window.topZ;
          const rect = win.getBoundingClientRect();
          offsetX = event.clientX - rect.left;
          offsetY = event.clientY - rect.top;
          head.setPointerCapture(event.pointerId);
        });

        head.addEventListener("pointermove", (event) => {
          if (!dragging) return;
          const bounds = $("#desktop").getBoundingClientRect();
          const rect = win.getBoundingClientRect();
          let left = event.clientX - bounds.left - offsetX;
          let top = event.clientY - bounds.top - offsetY;
          left = Math.max(4, Math.min(left, bounds.width - rect.width - 4));
          top = Math.max(35, Math.min(top, bounds.height - rect.height - 70));
          win.style.left = left + "px";
          win.style.top = top + "px";
        });

        head.addEventListener("pointerup", () => { dragging = false; });
        head.addEventListener("pointercancel", () => { dragging = false; });
      }

      makeDraggable(filesWindow);
      makeDraggable(notepadWindow);

      document.querySelectorAll(".window").forEach((win) => {
        win.addEventListener("pointerdown", () => {
          win.style.zIndex = ++window.topZ;
        });
      });

      function updateClock() {
        $("#clock").textContent = new Date().toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit"
        });
      }
      updateClock();
      setInterval(updateClock, 30000);
    })();
  </script>
</body>
</html>
